 cast(a,b,ignoreDoors=false){if(a.floorId!==b.floorId)return{t:0,wall:{kind:'floor'},x:a.x,y:a.y};const f=this.floors[a.floorId];let best=1,wall=null;for(const o of f.hash.query(Math.min(a.x,b.x),Math.min(a.y,b.y),Math.abs(b.x-a.x),Math.abs(b.y-a.y))){if(o.open||ignoreDoors&&f.data.doors.includes(o))continue;const t=hitSegment(a,b,o);if(t!==null&&t<=best){best=t;wall=o}}return{t:best,wall,x:a.x+(b.x-a.x)*best,y:a.y+(b.y-a.y)*best}}
